#define PI 3.14159265358


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv-=.5;
    uv.x*=iResolution.x/iResolution.y;
    uv*=10.;
    float time= iTime;
    float amplify=250.;

    vec3 col = vec3(
        getPX(
                uv, 
                1., 
                1., 
                vec2(
                    (tanh(cos(time*5.4)*5.)*.5+.5)*5.5,
                    0.
                ),
                time)
        *amplify
    );
    col-=texture(iChannel0, fragCoord/iResolution.xy+iTime).x*.1;

    col.r += smoothstep(.03,0.,abs(length(uv)-2.));

    // Output to screen
    fragColor = vec4(col,1.0);
}

vec2 mainSound( int samp, float time )
{
    float amplify = 100.4;
    float steps = 40.;
    float sensorSpread = 13.5;
    float val = 0.;
    for(float smpShft=0.; smpShft<1.; smpShft+=1.){
        for(float x=-1.; x<=1.; x+=2./steps){
            for(float y=-1.; y<=1.; y+=2./steps){
                val+=texture(iChannel0, vec2(.5+time+.3*x, .5+0.3*y)).y*10.3;
                val+=getPX(
                    vec2(x, y)*sensorSpread, 
                    signalFreq/numBlades, 
                    secondaryFreq*numBlades/1., 
                    vec2(
                        (tanh(cos(time*5.4)*5.)*.5+.5)*5.5,
                        0.
                    ),
                    time
                );
            }
        }
    }
    val/=steps*steps;

    //val=tanh(val*500.);
    val*=amplify;
    //val*=sin(time*130.*PI*2.)*.1;
    return vec2(val);
}

#define signalFreq 660.5
#define secondaryFreq 7500.
#define numBlades 24.
#define PI 3.14159265358

#define ambient 0.002
float getPX(vec2 uv, float rotSpeed, float gyroSpeed, vec2 target, float tim){
    // slightly 'wiggle' the time to achieve the wobblyness in the sound
    //float iTime = tim + sin(tim*PI*130.)*0.0004;
    float iTime=tim;
    float gyroDistance = 2.;//cos(iTime*gyroSpeed*.0002)*2.;
    vec2 discCenter = 1.*vec2(sin(iTime*gyroSpeed*PI*2.)*gyroDistance, cos(iTime*gyroSpeed*PI*2.)*gyroDistance);

    // Time varying pixel color
    float col = 0.;
    float cDist =length(discCenter-uv);
    float cAng = mod(atan(discCenter.x-uv.x,discCenter.y-uv.y)/PI/2.+iTime*rotSpeed, 1.) ;
    //col=smoothstep(.4,.6,sin(cDist*1.)*.5+.5); // radial lines


    float outerRing = tanh(50. * sin(cAng*36.*PI));
    // make disc-blades
    col = tanh(50. * sin(cAng*numBlades*PI));
    col = sin(cDist*PI*2.4)<0.?col:.1-col;
    col = cDist<.42 && abs(cAng-.75)>.075?0.5:col;
    // half transparent half circle
    col = cAng<.5 ? .5 : col;
    col = cDist>2.7?outerRing*1.:col;

    // target
    col*=50.*smoothstep(0.,2.,tanh(1.-pow(length(target-uv),.01))*1.)*(1.-ambient)+ambient;
    col *= smoothstep(3.,2.9,cDist);

    return col;
}
